Then('the localStorage todo items conform to the {string} schema in {string}', function (schemaId, schemaPath) {
  const schemaFile = path.resolve(ROOT, schemaPath);
  assert.ok(fs.existsSync(schemaFile), `schema file not found: ${schemaPath}`);
  const schema = JSON.parse(fs.readFileSync(schemaFile, 'utf8'));

  // Read todos from localStorage. TodoMVC typically stores under 'todos-*' key.
  // Find the key that starts with 'todos-'
  const ls = this.localStorage;
  let todosKey = null;
  for (let i = 0; i < ls.length; i++) {
    const k = ls.key(i);
    if (k && k.startsWith('todos-')) { todosKey = k; break; }
  }
  assert.ok(todosKey, 'expected a todos localStorage key (todos-*)');

  const raw = ls.getItem(todosKey);
  assert.ok(raw, `expected localStorage item "${todosKey}" to have a value`);
  let todos;
  try { todos = JSON.parse(raw); } catch (e) { assert.fail(`localStorage value is not valid JSON: ${e.message}`); }
  assert.ok(Array.isArray(todos), 'expected todos to be an array');

  // Validate each todo item against the schema
  for (let i = 0; i < todos.length; i++) {
    const item = todos[i];
    // Check required fields
    assert.ok(typeof item.id === 'string', `todo[${i}].id should be a string, got ${typeof item.id}`);
    assert.ok(typeof item.title === 'string', `todo[${i}].title should be a string, got ${typeof item.title}`);
    assert.ok(typeof item.completed === 'boolean', `todo[${i}].completed should be a boolean, got ${typeof item.completed}`);
    // Check no extra properties
    const allowed = ['id', 'title', 'completed'];
    const keys = Object.keys(item);
    for (const k of keys) {
      assert.ok(allowed.includes(k), `todo[${i}] has unexpected property "${k}"`);
    }
  }
});

(function () {
  'use strict';

  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;
  var STORAGE_KEY = 'todos-todomvc-shakedown';

  // -----------------------------------------------------------------------
  // Model
  // -----------------------------------------------------------------------

  function TodoStore() {
    this.todos = this.load();
  }

  TodoStore.prototype.load = function () {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      return raw ? JSON.parse(raw) : [];
    } catch (e) {
      return [];
    }
  };

  TodoStore.prototype.save = function () {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(this.todos));
  };

  TodoStore.prototype.nextId = function () {
    return Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
  };

  TodoStore.prototype.add = function (title) {
    var todo = {
      id: this.nextId(),
      title: title,
      completed: false
    };
    this.todos.push(todo);
    this.save();
    return todo;
  };

  TodoStore.prototype.remove = function (id) {
    this.todos = this.todos.filter(function (t) { return t.id !== id; });
    this.save();
  };

  TodoStore.prototype.update = function (id, props) {
    for (var i = 0; i < this.todos.length; i++) {
      if (this.todos[i].id === id) {
        for (var k in props) {
          if (props.hasOwnProperty(k)) {
            this.todos[i][k] = props[k];
          }
        }
        this.save();
        return;
      }
    }
  };

  TodoStore.prototype.toggle = function (id) {
    this.update(id, { completed: !this.get(id).completed });
  };

  TodoStore.prototype.get = function (id) {
    for (var i = 0; i < this.todos.length; i++) {
      if (this.todos[i].id === id) return this.todos[i];
    }
    return null;
  };

  TodoStore.prototype.active = function () {
    return this.todos.filter(function (t) { return !t.completed; });
  };

  TodoStore.prototype.completed = function () {
    return this.todos.filter(function (t) { return t.completed; });
  };

  TodoStore.prototype.toggleAll = function (checked) {
    for (var i = 0; i < this.todos.length; i++) {
      this.todos[i].completed = checked;
    }
    this.save();
  };

  TodoStore.prototype.clearCompleted = function () {
    this.todos = this.active();
    this.save();
  };

  // -----------------------------------------------------------------------
  // View / Controller
  // -----------------------------------------------------------------------

  var store = new TodoStore();
  var currentFilter = 'all';

  var todoapp = document.querySelector('.todoapp');
  var main = document.querySelector('.main');
  var footer = document.querySelector('.footer');
  var newTodo = document.querySelector('.new-todo');
  var todoList = document.querySelector('.todo-list');
  var toggleAll = document.querySelector('#toggle-all');
  var todoCount = document.querySelector('.todo-count');
  var clearCompleted = document.querySelector('.clear-completed');
  var filters = document.querySelectorAll('.filters a');

  function pluralize(count, word) {
    return count === 1 ? word : word + 's';
  }

  function getFilter() {
    var hash = location.hash.replace(/^#\/?/, '') || 'all';
    return hash === '' ? 'all' : hash;
  }

  function filterTodos(todos, filter) {
    if (filter === 'active') return store.active();
    if (filter === 'completed') return store.completed();
    return todos;
  }

  function bindFilterNav() {
    for (var i = 0; i < filters.length; i++) {
      filters[i].addEventListener('click', function (e) {
        e.preventDefault();
        var href = this.getAttribute('href');
        if (location.hash !== href) {
          location.hash = href;
        }
      });
    }
  }

  function updateFilterUI(filter) {
    for (var i = 0; i < filters.length; i++) {
      var a = filters[i];
      var href = a.getAttribute('href').replace('#/', '') || 'all';
      if (href === filter) {
        a.classList.add('selected');
      } else {
        a.classList.remove('selected');
      }
    }
  }

  function render() {
    var filter = getFilter();
    currentFilter = filter;
    updateFilterUI(filter);

    var items = filterTodos(store.todos, filter);
    var activeCount = store.active().length;

    // Build list HTML
    var html = '';
    for (var i = 0; i < items.length; i++) {
      var todo = items[i];
      var liClass = '';
      if (todo.completed) liClass += 'completed';
      html += '<li' + (liClass ? ' class="' + liClass + '"' : '') + ' data-id="' + todo.id + '">';
      html += '<div class="view">';
      html += '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>';
      html += '<label>' + escapeHtml(todo.title) + '</label>';
      html += '<button class="destroy"></button>';
      html += '</div>';
      html += '<input class="edit" value="' + escapeHtml(todo.title) + '">';
      html += '</li>';
    }
    todoList.innerHTML = html;

    // Toggle all
    toggleAll.checked = store.todos.length > 0 && activeCount === 0;

    // Main and footer visibility
    var hasTodos = store.todos.length > 0;
    main.style.display = hasTodos ? 'block' : 'none';
    footer.style.display = hasTodos ? 'block' : 'none';

    // Count
    todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + pluralize(activeCount, 'item') + ' left';

    // Clear completed visibility
    var completedCount = store.completed().length;
    clearCompleted.style.display = completedCount > 0 ? 'block' : 'none';

    // Wire up events on rendered items
    bindItemEvents();
  }

  function escapeHtml(str) {
    var div = document.createElement('div');
    div.appendChild(document.createTextNode(str));
    return div.innerHTML;
  }

  // -----------------------------------------------------------------------
  // Item-level events (re-bound after each render)
  // -----------------------------------------------------------------------

  function bindItemEvents() {
    // Toggle
    var toggles = todoList.querySelectorAll('.toggle');
    for (var i = 0; i < toggles.length; i++) {
      toggles[i].addEventListener('change', function () {
        var li = this.closest('li');
        if (!li) return;
        var id = li.getAttribute('data-id');
        store.toggle(id);
        render();
      });
    }

    // Destroy
    var destroys = todoList.querySelectorAll('.destroy');
    for (var i = 0; i < destroys.length; i++) {
      destroys[i].addEventListener('click', function () {
        var li = this.closest('li');
        if (!li) return;
        var id = li.getAttribute('data-id');
        store.remove(id);
        render();
      });
    }

    // Double-click to edit
    var labels = todoList.querySelectorAll('.view label');
    for (var i = 0; i < labels.length; i++) {
      labels[i].addEventListener('dblclick', function () {
        var li = this.closest('li');
        if (!li) return;
        li.classList.add('editing');
        var editInput = li.querySelector('.edit');
        editInput.focus();
        editInput.value = editInput.value;
      });
    }

    // Edit handlers
    var edits = todoList.querySelectorAll('.edit');
    for (var i = 0; i < edits.length; i++) {
      edits[i].addEventListener('keydown', function (e) {
        var li = this.closest('li');
        if (!li) return;
        var id = li.getAttribute('data-id');

        if (e.keyCode === ENTER_KEY) {
          var val = this.value.trim();
          if (val) {
            store.update(id, { title: val });
          } else {
            store.remove(id);
          }
          li.classList.remove('editing');
          render();
        } else if (e.keyCode === ESCAPE_KEY) {
          var original = store.get(id);
          this.value = original ? original.title : '';
          li.classList.remove('editing');
        }
      });

      edits[i].addEventListener('blur', function () {
        var li = this.closest('li');
        if (!li) return;
        if (!li.classList.contains('editing')) return;
        var id = li.getAttribute('data-id');
        var val = this.value.trim();
        if (val) {
          store.update(id, { title: val });
        } else {
          store.remove(id);
        }
        li.classList.remove('editing');
        render();
      });
    }
  }

  // -----------------------------------------------------------------------
  // Global events
  // -----------------------------------------------------------------------

  newTodo.addEventListener('keydown', function (e) {
    if (e.keyCode === ENTER_KEY) {
      var val = this.value.trim();
      if (val) {
        store.add(val);
        this.value = '';
        render();
      }
    }
  });

  toggleAll.addEventListener('change', function () {
    store.toggleAll(this.checked);
    render();
  });

  clearCompleted.addEventListener('click', function () {
    store.clearCompleted();
    render();
  });

  window.addEventListener('hashchange', function () {
    render();
  });

  bindFilterNav();

  // -----------------------------------------------------------------------
  // Bootstrap
  // -----------------------------------------------------------------------

  render();
})();

