edits.newText:
When('I reload the app', function () {
  // Save raw localStorage data before dispose (as plain strings, not references)
  const ls = this.localStorage;
  const savedData = {};
  for (var i = 0; i < ls.length; i++) {
    var k = ls.key(i);
    savedData[k] = ls.getItem(k);
  }
  return this.disposeApp().then(() => {
    // Create a new window, pre-populate localStorage, then load the app
    this.window = new this.window.constructor({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // Pre-set localStorage so the app reads persisted data on init
    for (var k in savedData) {
      if (savedData.hasOwnProperty(k)) {
        this.localStorage.setItem(k, savedData[k]);
      }
    }

    var indexPath = require('node:path').resolve(require('node:path').dirname(require('node:path').resolve(__dirname, '..', '..')));
    this.document.write(require('node:fs').readFileSync(require('node:path').resolve(indexPath, 'index.html'), 'utf8'));
    this.document.close();
    this.window.eval(require('node:fs').readFileSync(require('node:path').resolve(indexPath, 'js', 'app.js'), 'utf8'));
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // Register click-to-hashchange handler same as world.js does
    var w = this.window;
    this.document.addEventListener('click', function (e) {
      var a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      var next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
  });
});

